validate:
(result, args) => {
  const original = args[0];
  if (!Array.isArray(result) || result.length !== 2) return "Return a pair: [serialize(root), deserialize(serialize(root))].";
  const [text, back] = result;
  if (typeof text !== "string") return "serialize must return a string, but got " + (text === null ? "null" : typeof text) + ".";
  const got = back === null || back === undefined ? [] : back;
  if (JSON.stringify(got) !== JSON.stringify(original)) return "Deserializing " + JSON.stringify(text) + " rebuilt the tree " + JSON.stringify(got) + " (level order), but the original was " + JSON.stringify(original) + ".";
  return true;
}
